class s{constructor(){this.cartItems=[],this.cartId=null,this.loadCartFromStorage()}loadCartFromStorage(){try{const t=localStorage.getItem("deliwer_cart");if(t){const a=JSON.parse(t);this.cartItems=a.items||[],this.cartId=a.cartId||null}}catch(t){console.error("Failed to load cart from storage:",t),this.clearCart()}}saveCartToStorage(){try{localStorage.setItem("deliwer_cart",JSON.stringify({items:this.cartItems,cartId:this.cartId,updatedAt:new Date().toISOString()}))}catch(t){console.error("Failed to save cart to storage:",t)}}async addToCart(t){const a=this.cartItems.find(r=>r.variantId===t.variantId);if(a)a.quantity+=t.quantity||1;else{const r={id:`cart_${Date.now()}_${Math.random().toString(36).substr(2,9)}`,variantId:t.variantId,productId:t.id,title:t.title,variant:t.variant||"Default",price:t.price,quantity:t.quantity||1,image:t.image,available:!0};this.cartItems.push(r)}this.saveCartToStorage(),await this.syncWithShopify()}async updateCartItem(t,a){const r=this.cartItems.find(e=>e.id===t);r&&(r.quantity=a,this.saveCartToStorage(),await this.syncWithShopify())}async removeCartItem(t){this.cartItems=this.cartItems.filter(a=>a.id!==t),this.saveCartToStorage(),await this.syncWithShopify()}async getCartItems(){return await this.checkAvailability(),this.cartItems}getCartCount(){return this.cartItems.reduce((t,a)=>t+a.quantity,0)}getCartTotal(){return this.cartItems.reduce((t,a)=>t+a.price*a.quantity,0)}async clearCart(){this.cartItems=[],this.cartId=null,this.saveCartToStorage()}async createCheckout(t){try{const a=t.map(i=>({variantId:i.variantId,quantity:i.quantity})),r=await fetch("/api/shopify/checkout",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({lineItems:a,customAttributes:[{key:"source",value:"deliwer_metaverse"}]})});if(!r.ok)throw new Error("Failed to create checkout");const{checkoutUrl:e}=await r.json();return e}catch(a){throw console.error("Checkout creation error:",a),new Error("Failed to create checkout session")}}async syncWithShopify(){try{const t=localStorage.getItem("deliwer_token");if(!t||this.cartItems.length===0)return;const a=await fetch("/shopify/cart/sync",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${t}`},body:JSON.stringify({cartId:this.cartId,items:this.cartItems.map(r=>({variantId:r.variantId,quantity:r.quantity}))})});if(a.ok){const{cartId:r}=await a.json();this.cartId=r,this.saveCartToStorage()}}catch(t){console.error("Cart sync error:",t)}}async checkAvailability(){try{if(this.cartItems.length===0)return;const t=this.cartItems.map(r=>r.variantId),a=await fetch("/shopify/variants/availability",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({variantIds:t})});if(a.ok){const r=await a.json();this.cartItems.forEach(e=>{const i=r[e.variantId];e.available=(i==null?void 0:i.available)||!1}),this.saveCartToStorage()}}catch(t){console.error("Availability check error:",t)}}}const c=new s;export{c as s};
